      "Administração direta é o conjunto de órgãos que integram a estrutura da própria pessoa jurídica política (União, Estados, Distrito Federal e Municípios), sem personalidade jurídica própria — são apenas centros de competência dentro do ente federativo (ministérios, secretarias). Administração indireta é formada por pessoas jurídicas próprias, criadas para descentralizar a execução de atividades administrativas: autarquias, fundações públicas, empresas públicas e sociedades de economia mista.",
      "Autarquia é pessoa jurídica de direito público, criada por lei específica, para executar atividades típicas de Estado (ex.: INSS, IBAMA) — tem os mesmos privilégios processuais e tributários da Fazenda Pública, seus bens são públicos (impenhoráveis) e seu regime de pessoal é estatutário. Fundação pública de direito público tem regime semelhante ao da autarquia; fundação pública de direito privado se aproxima mais das empresas estatais.",
      "Empresa pública tem capital 100% público (pode ter mais de um ente federativo como sócio, mas nunca capital privado), constituída sob qualquer forma societária admitida em direito. Sociedade de economia mista tem capital misto (público e privado), mas o controle acionário deve ser sempre da entidade estatal, e sua forma societária é obrigatoriamente a sociedade anônima. Ambas se submetem a regime jurídico de direito privado predominante (empregados regidos pela CLT), mas com derrogações de direito público (concurso público para admissão, submissão a controle externo, vedação a falência)."
