      "Revogação: conveniência/oportunidade, efeitos só para o futuro (ex nunc), só a Administração pode revogar (nunca o Judiciário).",
      "Prazo decadencial de 5 anos para a Administração anular atos favoráveis, salvo comprovada má-fé."
