      "justificativa": "Como o ato é válido (sem vício de legalidade) e a mudança se dá por razão de conveniência administrativa, a medida cabível é a revogação — e apenas a própria Administração pode revogar seus atos, nunca o Poder Judiciário, que só pode anular atos ilegais."
